// v28.xx (cw-cleanwords), HIS ANSWER (2026-10-18, Q76): clean the swearing out of on-screen lines and keep the attitude. Three of his baked lines
// (Q8: a changed line gets its reason in notes/ui/changes.md): "You cheap bastard." is now "You cheapskate.", "Shit's about to get real." is now
// "Things are about to get real.", and "This is some shit Claude came up with." is now "This is some wild idea Claude came up with."
var TXSHIP={

check:
{v:'VER',what:'no swearing in the baked on-screen lines (his answer Q76): the three lines that had it keep their attitude without it',
 run:function(){
   if(typeof TXSHIP!=='object'||!TXSHIP) return 'no TXSHIP table';
   var bad=[], k, v, rx=/\b(shit\w*|fuck\w*|bastards?|damn\w*|hell|bitch\w*|crap\w*|asshole|ass|piss\w*)\b/i, n=0, sw=0;
   for(k in TXSHIP){ v=String(TXSHIP[k]); n++; if(rx.test(v)){ sw++; bad.push('swearing in: '+v.slice(0,60)); } }
   if(n<20) bad.push('the table is gone ('+n+' lines)');
   var cs=0, rg=0, wi=0;
   for(k in TXSHIP){ v=String(TXSHIP[k]); if(/cheapskate/.test(v)) cs++; if(/about to get real/.test(v)) rg++; if(/wild idea Claude/.test(v)) wi++; }
   if(cs!==1||rg!==1||wi!==1) bad.push('the cleaned lines lost their attitude (cheapskate '+cs+', get real '+rg+', wild idea '+wi+')');
   return bad.length?bad.join('; '):null; }},
